/* eslint-enable prettier/prettier */
const YEARS = [2025, 2026];

const PERIOD_BY_COUNT = {
  260: "daily",
  52: "weekly",
  26: "biweekly",
  24: "semimonthly",
  12: "monthly",
  4: "quarterly",
  2: "semiannual",
  1: "annual",
};
const STATUSES = ["single", "marriedJoint", "marriedSeparate", "headOfHousehold", "qualifyingWidow"];
const RATES = ["A", "B", "C", "D", "E"];

function validateForm(form) {
  if (form === null || form === undefined) return;
  const fail = (m) => {
    throw new Error(`New Jersey NJ-W4: ${m}`);
  };
  if (!STATUSES.includes(form.filingStatus)) fail(`filingStatus must be one of ${STATUSES.join(", ")}`);
  if (form.rateTable !== undefined && form.rateTable !== null && !RATES.includes(form.rateTable)) {
    fail("rateTable (line 3) must be A, B, C, D or E");
  }
  const n = form.allowances ?? 0;
  if (!Number.isInteger(n) || n < 0) fail("allowances must be a non-negative integer");
  const extra = form.additionalWithholdingCents ?? 0;
  if (!Number.isSafeInteger(extra) || extra < 0) fail("additionalWithholdingCents must be a non-negative integer");
}

function rateTableFor(form) {
  if (form.rateTable) return form.rateTable;
  return form.filingStatus === "single" || form.filingStatus === "marriedSeparate" ? "A" : "B";
}

function compute({ wagesCents, payPeriodsPerYear, form }) {
  const t = TABLES.shared;
  const period = PERIOD_BY_COUNT[payPeriodsPerYear];
  if (!period) throw new Error(`New Jersey has no rate table for ${payPeriodsPerYear} pay periods a year`);
  validateForm(form);

  const onFile = form !== null && form !== undefined;
  if (onFile && form.exempt) return { stateCents: 0, formBasis: "exempt", lines: {} };
  const f = onFile ? form : { filingStatus: "single", allowances: 0 };
  const rateTable = rateTableFor(f);

  const taxable = Math.max(0, wagesCents - (f.allowances ?? 0) * t.allowanceCents[period]);
  const rows = t.rates[rateTable][period];
  let row = rows[0];
  for (const r of rows) if (taxable > r[0]) row = r; // "Over"
  const [over, base, rateBp] = row;
  const tax = Math.round(base + ((taxable - over) * rateBp) / 10_000);

  return {
    stateCents: tax + (f.additionalWithholdingCents ?? 0),
    formBasis: onFile ? "nj-w4" : "none-on-file-rate-a-zero",
    lines: { rateTable, taxableCents: taxable },
  };
}

module.exports = {
  code: "NJ",
  name: "New Jersey",
  wageBasis: "federal-income-tax-wages",
  years: YEARS,
  TABLES,
  validateForm,
  compute,
};
